fn managed_resource_telemetry(
    config: &ManagedModelConfig,
) -> Result<ModelResourceTelemetry, NativeAgentError> {
    Ok(ModelResourceTelemetry {
        resident: TelemetryValue::Measured(ManagedLocalRuntime::is_resident(&config.config)?),
        representation_size_bytes: TelemetryValue::Measured(config.config.model_size_bytes),
        gpu_residency_bytes: TelemetryValue::Unavailable,
        context_length_tokens: TelemetryValue::Unavailable,
    })
}

fn execute_managed_resource_operation(
    config: &ManagedModelConfig,
    operation: ModelResourceOperation,
) -> Result<ModelResourceTransition, NativeAgentError> {
    let before = managed_resource_telemetry(config)?;
    let started = Instant::now();
    let backend_load_latency_ms = match operation {
        ModelResourceOperation::Observe => TelemetryValue::Unavailable,
        ModelResourceOperation::Release => {
            ManagedLocalRuntime::stop_for_config(&config.config)?;
            TelemetryValue::Unavailable
        }
        ModelResourceOperation::Reload => {
            let load_started = Instant::now();
            ManagedLocalRuntime::ensure_endpoint(&config.config)?;
            TelemetryValue::Measured(duration_ms(load_started.elapsed()))
        }
        ModelResourceOperation::ReduceGpuResidency => {
            return Err(NativeAgentError::UnsupportedCapability(
                "verified dynamic CPU/GPU offload for managed llama.cpp".to_owned(),
            ));
        }
    };
    let after = managed_resource_telemetry(config)?;
    if !resource_transition_confirmed(operation, &before, &after) {
        return Err(NativeAgentError::ResourceTransitionUnconfirmed(format!(
            "managed {operation:?} did not produce verified process residency telemetry"
        )));
    }
    Ok(ModelResourceTransition {
        operation,
        before,
        after,
        operation_latency_ms: TelemetryValue::Measured(duration_ms(started.elapsed())),
        backend_load_latency_ms,
    })
}

